    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const book = document.getElementById('myBook');
            const pages = book.querySelectorAll('.page');
            let currentPage = 0;
            book.addEventListener('click', (e) => {
                if (e.target.classList.contains('clickable')) return;
                if (currentPage < pages.length - 1) {
                    pages[currentPage].classList.add('flipped');
                    currentPage++;
                } else {
                    pages.forEach(page => page.classList.remove('flipped'));
                    currentPage = 0;
                }
            });

            const modal = document.getElementById('infoModal');
            const modalBody = document.getElementById('modalBody');
            const closeBtn = document.querySelector('.close');
            closeBtn.onclick = () => { modal.style.display = 'none'; };
            window.onclick = (event) => { if (event.target == modal) { modal.style.display = 'none'; } };

            function showModal(content) {
                modalBody.innerHTML = content;
                modal.style.display = 'flex';
            }

            // --- 动态渲染关系 ---
            try {
                const relationsData = JSON.parse(`$5`);
                const relationsList = document.getElementById('relationsList');
                relationsData.forEach(rel => {
                    const li = document.createElement('li');
                    li.innerHTML = `<strong>${rel.name}:</strong> <span class="clickable">${rel.mood}</span>`;
                    li.querySelector('.clickable').addEventListener('click', () => {
                        showModal(`<h3>${rel.name}</h3><p><strong>好感度:</strong> ${rel.mood}</p><p><strong>内心想法:</strong> ${rel.thought}</p>`);
                    });
                    relationsList.appendChild(li);
                });
            } catch (e) { console.error('关系数据解析失败:', e); }

            // --- 动态渲染道具 ---
            try {
                const itemsData = JSON.parse(`$6`);
                const itemsList = document.getElementById('itemsList');
                itemsData.forEach(item => {
                    const li = document.createElement('li');
                    li.className = 'clickable';
                    li.textContent = item.name;
                    li.addEventListener('click', () => {
                        showModal(`<h3>${item.name}</h3><p><strong>数量:</strong> ${item.count}</p><p><strong>来源:</strong> ${item.source}</p><p><strong>作用:</strong> ${item.effect}</p>`);
                    });
                    itemsList.appendChild(li);
                });
            } catch (e) { console.error('道具数据解析失败:', e); }
        });
    </script>
</body>
</html>
